//! 1.7.10 overworld terrain shaper (ChunkProviderGenerate terrain half).
//!
//! Ports aqz provideChunk's first stage: density field `q[5*33*5]` from the
//! GenLayer biome array + octave stacks, then trilinear fill into block ids
//! (stone=1, water=9, air=0). Surface builder, carvers and decorators are
//! separate stages (H2 follow-ups); goldens below pin this stage.
//!
//! Method bodies verified against CFR decompile of the official server jar;
//! goldens are live JVM outputs (FieldDump harness), not re-derivations.

const std = @import("std");
const java_random = @import("../rng/java_random.zig");
const noise = @import("noise.zig");
const genlayer = @import("genlayer.zig");
const biome = @import("biome.zig");
const surface = @import("surface.zig");

pub const SEA_LEVEL: i32 = 63;
pub const Q_LEN: usize = 5 * 33 * 5;
pub const BLOCKS_LEN: usize = 16 * 256 * 16;

pub const STONE: u16 = 1;
pub const WATER: u16 = 9;
pub const AIR: u16 = 0;

pub const Shaper = struct {
    min_s: noise.Octaves, // j, 16 octaves
    max_s: noise.Octaves, // k, 16
    main_s: noise.Octaves, // l, 8
    surf_s: noise.SimplexOctaves, // m, 4 (surface stone noise; used by next stage)
    depth10: noise.Octaves, // a, 10 (constructed for RNG fidelity; unused)
    depth_s: noise.Octaves, // b, 16 (5x5 depth field)
    forest8: noise.Octaves, // c, 8 (constructed for RNG fidelity; unused)
    par_w: [25]f32,
    chain: genlayer.Chain,
    roots: [3]u32,
    temp_eval: surface.TempEval,
    mesa: surface.MesaState,
    amplified: bool,
    alloc: std.mem.Allocator,

    pub fn init(alloc: std.mem.Allocator, world_seed: i64, large_biomes: bool, amplified: bool) !Shaper {
        // NOTE: construction order is spec — one shared Random, stacks draw
        // sequentially (verified by octave goldens).
        var r = java_random.JavaRandom.init(world_seed);
        var s = Shaper{
            .min_s = try noise.Octaves.init(alloc, &r, 16),
            .max_s = try noise.Octaves.init(alloc, &r, 16),
            .main_s = try noise.Octaves.init(alloc, &r, 8),
            .surf_s = try noise.SimplexOctaves.init(alloc, &r, 4),
            .depth10 = try noise.Octaves.init(alloc, &r, 10),
            .depth_s = try noise.Octaves.init(alloc, &r, 16),
            .forest8 = try noise.Octaves.init(alloc, &r, 8),
            .par_w = undefined,
            .chain = undefined,
            .roots = undefined,
            .temp_eval = undefined,
            .mesa = undefined,
            .amplified = amplified,
            .alloc = alloc,
        };
        errdefer s.deinit();
        for (0..5) |udi| {
            for (0..5) |udj| {
                const i: i32 = @as(i32, @intCast(udi)) - 2;
                const j: i32 = @as(i32, @intCast(udj)) - 2;
                const fi: f32 = @floatFromInt(i);
                const fj: f32 = @floatFromInt(j);
                // NOTE: qh.c(float) is float sqrt; @sqrt(f32) matches bit-exact.
                s.par_w[udi + udj * 5] = 10.0 / @sqrt(fi * fi + fj * fj + 0.2);
            }
        }
        const built = try genlayer.Chain.buildDefault(alloc, world_seed, large_biomes);
        s.chain = built.chain;
        s.roots = built.roots;
        s.temp_eval = try surface.TempEval.init(alloc);
        s.mesa = try surface.MesaState.init(alloc, world_seed);
        return s;
    }

    pub fn deinit(self: *Shaper) void {
        self.min_s.deinit();
        self.max_s.deinit();
        self.main_s.deinit();
        self.surf_s.deinit();
        self.depth10.deinit();
        self.depth_s.deinit();
        self.forest8.deinit();
        self.temp_eval.deinit();
        self.mesa.deinit();
        self.chain.deinit();
    }

    /// Density field q[825] for chunk (cx,cz). Scratch arena for temporaries.
    pub fn densityField(self: *Shaper, scratch: std.mem.Allocator, cx: i32, cz: i32, q: *[Q_LEN]f64) !void {
        // Biome array 10x10 via the biome (final_mix) root.
        const bz = try scratch.alloc(i32, 100);
        defer scratch.free(bz);
        try self.chain.getInts(scratch, self.roots[0], cx * 4 - 2, cz * 4 - 2, 10, 10, bz);
        var bam: [100]f32 = undefined;
        var ban: [100]f32 = undefined;
        for (bz, 0..) |id, i| {
            const h = biome.HEIGHTS[@as(usize, @intCast(@as(u32, @bitCast(id)) & 255))];
            bam[i] = h[0];
            ban[i] = h[1];
        }
        const n = cx * 4;
        const n3 = cz * 4;
        // Depth field g[25] via the 16-octave stack, 2D entry.
        const g = try scratch.alloc(f64, 25);
        defer scratch.free(g);
        @memset(g, 0.0);
        _ = self.depth_s.generate(g, n, 10, n3, 5, 1, 5, 200.0, 1.0, 200.0);
        const dd = try scratch.alloc(f64, Q_LEN);
        defer scratch.free(dd);
        @memset(dd, 0.0);
        _ = self.main_s.generate(dd, n, 0, n3, 5, 33, 5, 8.55515, 4.277575, 8.55515);
        const e = try scratch.alloc(f64, Q_LEN);
        defer scratch.free(e);
        @memset(e, 0.0);
        _ = self.min_s.generate(e, n, 0, n3, 5, 33, 5, 684.412, 684.412, 684.412);
        const f = try scratch.alloc(f64, Q_LEN);
        defer scratch.free(f);
        @memset(f, 0.0);
        _ = self.max_s.generate(f, n, 0, n3, 5, 33, 5, 684.412, 684.412, 684.412);
        var n4: usize = 0;
        var n5: usize = 0;
        for (0..5) |i| {
            for (0..5) |j| {
                var bf: f32 = 0;
                var bf2: f32 = 0;
                var bf3: f32 = 0;
                const center_am = bam[i + 2 + (j + 2) * 10];
                for (0..5) |di| {
                    for (0..5) |dj| {
                        const bi = (i + di) + (j + dj) * 10;
                        var f4 = bam[bi];
                        var f5 = ban[bi];
                        if (self.amplified and f4 > 0.0) {
                            f4 = 1.0 + f4 * 2.0;
                            f5 = 1.0 + f5 * 4.0;
                        }
                        var f6 = self.par_w[di + dj * 5] / (f4 + 2.0);
                        if (bam[bi] > center_am) f6 /= 2.0;
                        bf += f5 * f6;
                        bf2 += f4 * f6;
                        bf3 += f6;
                    }
                }
                bf /= bf3;
                bf2 /= bf3;
                bf = bf * 0.9 + 0.1;
                bf2 = (bf2 * 4.0 - 1.0) / 8.0;
                var d6 = g[n5] / 8000.0;
                if (d6 < 0.0) d6 = -d6 * 0.3;
                d6 = d6 * 3.0 - 2.0;
                if (d6 < 0.0) {
                    d6 /= 2.0;
                    if (d6 < -1.0) d6 = -1.0;
                    d6 /= 1.4;
                    d6 /= 2.0;
                } else {
                    if (d6 > 1.0) d6 = 1.0;
                    d6 /= 8.0;
                }
                n5 += 1;
                var d7: f64 = @as(f64, bf2) + d6 * 0.2;
                d7 = d7 * 8.5 / 8.0;
                const d8: f64 = bf;
                const d9 = 8.5 + d7 * 4.0;
                for (0..33) |y| {
                    const yf: f64 = @floatFromInt(y);
                    var d10 = (yf - d9) * 12.0 * 128.0 / 256.0 / d8;
                    if (d10 < 0.0) d10 *= 4.0;
                    const d11 = e[n4] / 512.0;
                    const d12 = f[n4] / 512.0;
                    const d13 = (dd[n4] / 10.0 + 1.0) / 2.0;
                    // NOTE: qh.b = clamped lerp (verified CFR).
                    const lerped = if (d13 < 0.0) d11 else if (d13 > 1.0) d12 else d11 + (d12 - d11) * d13;
                    var d14 = lerped - d10;
                    if (y > 29) {
                        // NOTE: (float)(y-29)/3.0f in f32, then widened.
                        const d15: f64 = @as(f64, (@as(f32, @floatFromInt(y - 29)) / 3.0));
                        d14 = d14 * (1.0 - d15) + -10.0 * d15;
                    }
                    q[n4] = d14;
                    n4 += 1;
                }
            }
        }
    }

    /// Trilinear fill: q[825] -> block ids (stone/water/air).
    /// Index order mirrors vanilla exactly (see port notes in H2 log).
    pub fn fillChunk(q: *const [Q_LEN]f64, blocks: *[BLOCKS_LEN]u16) void {
        @memset(blocks, AIR);
        for (0..4) |i| {
            for (0..4) |j| {
                const n6 = (i * 5 + j) * 33;
                const n7 = (i * 5 + j + 1) * 33;
                const n8 = ((i + 1) * 5 + j) * 33;
                const n9 = ((i + 1) * 5 + j + 1) * 33;
                for (0..32) |cy| {
                    var d2 = q[n6 + cy];
                    var d3 = q[n7 + cy];
                    var d4 = q[n8 + cy];
                    var d5 = q[n9 + cy];
                    const d6 = (q[n6 + cy + 1] - d2) * 0.125;
                    const d7 = (q[n7 + cy + 1] - d3) * 0.125;
                    const d8 = (q[n8 + cy + 1] - d4) * 0.125;
                    const d9 = (q[n9 + cy + 1] - d5) * 0.125;
                    for (0..8) |fy| {
                        var d11 = d2;
                        var d12 = d3;
                        const d13 = (d4 - d2) * 0.25;
                        const d14 = (d5 - d3) * 0.25;
                        for (0..4) |fx| {
                            // NOTE: x<<12 | z<<8 | y with z = j*4 (+fz stride).
                            // Signed index: base can be < 256 (vanilla int wraps).
                            var n10: i32 = @as(i32, @intCast(((fx + i * 4) << 12) | ((j * 4) << 8) | (cy * 8 + fy)));
                            n10 -= 256;
                            var d16 = d11;
                            const d17 = (d12 - d11) * 0.25;
                            // NOTE: d16 starts d11-d17; exact op order is spec.
                            d16 -= d17;
                            for (0..4) |_| {
                                d16 += d17;
                                n10 += 256;
                                const y: i32 = @intCast(cy * 8 + fy);
                                blocks[@as(usize, @intCast(n10))] = if (d16 > 0.0) STONE else if (y < SEA_LEVEL) WATER else AIR;
                            }
                            d11 += d13;
                            d12 += d14;
                        }
                        d2 += d6;
                        d3 += d7;
                        d4 += d8;
                        d5 += d9;
                    }
                }
            }
        }
    }

    /// Full surface pass over filled blocks (ahu.b per column).
    /// meta is a full byte-per-cell array (ZC1 packs nibbles later).
    pub fn surfaceChunk(self: *Shaper, scratch: std.mem.Allocator, cx: i32, cz: i32, blocks: *[BLOCKS_LEN]u16, meta: *[BLOCKS_LEN]u8) !void {
        @memset(meta, 0);
        const s = try scratch.alloc(f64, 256);
        defer scratch.free(s);
        @memset(s, 0.0);
        // NOTE: awl 8-arg (xsc, zsc, freq=1.0) + hardcoded amp 0.5.
        _ = self.surf_s.grid(s, cx * 16, cz * 16, 16, 16, 0.0625, 0.0625, 1.0, 0.5);
        const bio = try scratch.alloc(i32, 256);
        defer scratch.free(bio);
        try self.chain.getInts(scratch, self.roots[1], cx * 16, cz * 16, 16, 16, bio);
        var r = java_random.JavaRandom.init(0);
        r.setSeed(@as(i64, cx) *% 341873128712 +% @as(i64, cz) *% 132897987541);
        for (0..16) |i| {
            for (0..16) |j| {
                const bio_id = bio[j + i * 16];
                if (surface.isMesa(bio_id)) {
                    surface.mesaBuildColumn(
                        blocks,
                        meta,
                        i,
                        j,
                        cx * 16 + @as(i32, @intCast(i)),
                        cz * 16 + @as(i32, @intCast(j)),
                        s[j + i * 16],
                        &r,
                        &self.mesa,
                        bio_id == 165,
                        bio_id == 38 or bio_id == 166,
                    );
                } else {
                    surface.buildColumn(
                        blocks,
                        meta,
                        i,
                        j,
                        cx * 16 + @as(i32, @intCast(i)),
                        cz * 16 + @as(i32, @intCast(j)),
                        s[j + i * 16],
                        &r,
                        bio_id,
                        &self.temp_eval,
                    );
                }
            }
        }
    }
};
fn qKahan(a: []const f64) f64 {
    var s: f64 = 0.0;
    var c: f64 = 0.0;
    for (a) |v| {
        const y = v - c;
        const t = s + y;
        c = (t - s) - y;
        s = t;
    }
    return s;
}

fn blocksCrc(b: []const u16) i64 {
    var c: i64 = 0;
    for (b) |v| c = c *% 31 +% @as(i64, v);
    return c;
}

