fn metaCrc(m: []const u8) i64 {
    var c: i64 = 0;
    for (m) |v| c = c *% 31 +% @as(i64, v);
    return c;
}

test "surface matches JVM (seed 1 chunk 0,0)" {
    const alloc = std.testing.allocator;
    var sh = try Shaper.init(alloc, 1, false, false);
    defer sh.deinit();
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    var q: [Q_LEN]f64 = undefined;
    try sh.densityField(arena.allocator(), 0, 0, &q);
    var blocks: [BLOCKS_LEN]u16 = undefined;
    Shaper.fillChunk(&q, &blocks);
    var meta: [BLOCKS_LEN]u8 = undefined;
    try sh.surfaceChunk(arena.allocator(), 0, 0, &blocks, &meta);
    // JVM: 0:49408 1:10822 7:762 9:4288 13:256
    try std.testing.expectEqual(@as(i64, 1984205357247477528), blocksCrc(&blocks));
    try std.testing.expectEqual(@as(i64, 0), metaCrc(&meta));
